import unittest

from solucao import pedaco
from solucao import pedaco_depois


class TestUmPedacoDaLista(unittest.TestCase):
    def test_pega_o_meio(self):
        """pedaco devolve do inicio ate um antes do fim"""
        self.assertEqual(pedaco(["a", "b", "c", "d"], 1, 3), ["b", "c"])

    def test_pedaco_vazio(self):
        """pedaco com inicio igual ao fim devolve lista vazia"""
        self.assertEqual(pedaco(["a", "b", "c"], 1, 1), [])

    def test_pedaco_depois_do_item(self):
        """pedaco_depois devolve o pedaco que comeca um depois do item"""
        self.assertEqual(pedaco_depois(["a", "b", "c", "d"], "b"), ["c", "d"])

    def test_pedaco_depois_do_ultimo(self):
        """pedaco_depois do ultimo item devolve lista vazia"""
        self.assertEqual(pedaco_depois(["a", "b", "c"], "c"), [])

